output_schema:
Static analysis findings categorized by type and severity
{
  "syntax_analysis": {
    "issues": [
      {
        "line": "number",
        "code": "string - The problematic code",
        "issue": "string - Description of the problem",
        "severity": "error | warning | info",
        "suggestion": "string - How to fix"
      }
    ],
    "style_violations": ["string"]
  },
  "type_safety": {
    "issues": [
      {
        "line": "number",
        "type_error": "string",
        "expected": "string",
        "actual": "string",
        "fix": "string"
      }
    ],
    "any_usage": ["string - Lines with 'any' or equivalent"]
  },
  "complexity_analysis": {
    "functions_analyzed": "number",
    "high_complexity": [
      {
        "name": "string - Function name",
        "line": "number",
        "cyclomatic_complexity": "number",
        "recommendation": "string"
      }
    ],
    "deep_nesting": [
      {
        "line": "number",
        "depth": "number",
        "suggestion": "string"
      }
    ]
  },
  "code_smells": [
    {
      "type": "string - e.g., 'magic-number', 'duplicate-code', 'long-method'",
      "location": "string",
      "description": "string",
      "refactoring_suggestion": "string"
    }
  ],
  "summary": {
    "total_issues": "number",
    "by_severity": {
      "error": "number",
      "warning": "number",
      "info": "number"
    },
    "ready_for_security_review": "boolean"
  }
}
